using System;
using System.Linq;
using Wip.Bones.Domain;
using Wip.Bones.Engine;

public sealed class SeatStrategy : IBonesPlayerSlot
{
    public BonesMove ChooseMove(BonesRoundState state, IReadOnlyList<BonesMove> legalMoves)
    {
        // Try to find a move that plays a tile to match a board end
        foreach (var move in legalMoves)
        {
            if (move.IsPass)
                continue;

            var tile = move.Tile.Value;

            // Check if tile can be placed on either end
            int leftPip = state.Board.LeftEnd?.Pip.Value ?? -1;
            int rightPip = state.Board.RightEnd?.Pip.Value ?? -1;

            // Prefer playing doubles when possible
            if (tile.IsDouble && (tile.LowPip.Value == leftPip || tile.LowPip.Value == rightPip))
                return move;

            // Play highest pip matching tile
            if (tile.LowPip.Value == leftPip || tile.HighPip.Value == leftPip ||
                tile.LowPip.Value == rightPip || tile.HighPip.Value == rightPip)
                return move;
        }

        // If no matching tile, play highest total pip tile
        var bestTile = legalMoves
            .Where(m => !m.IsPass)
            .OrderByDescending(m => m.Tile.Value.TotalPips)
            .FirstOrDefault();

        if (bestTile != null)
            return bestTile;

        // If no plays available, pass
        var passMove = legalMoves.FirstOrDefault(m => m.IsPass);
        if (passMove != null)
            return passMove;

        // Should never reach here if legal moves are valid
        throw new InvalidOperationException("No legal move available");
    }
}
